{"ok":true,"result":{"path":"/src/agent-ui/plugins/quick-help-card/index.tsx","content":"1: import { useAgentUILocaleCode } from "@za38.03/agent-ui-plugins";
2: import { useId, useState } from "react";
3: import type { ReactNode } from "react";
4: import "./styles.css";
5: 
6: type QuickHelpCardProps = {
7:   renderSlot?: (name: string, fallback?: ReactNode) => ReactNode;
8: };
9: 
10: const messages: Record<string, { title: string; expand: string; collapse: string }> = {
11:   "zh-CN": { title: "使用帮助", expand: "展开", collapse: "折叠" },
12:   "en-US": { title: "Usage Help", expand: "Expand", collapse: "Collapse" },
13: };
14: 
15: export function QuickHelpCardPlugin(props: QuickHelpCardProps) {
16:   const localeCode = useAgentUILocaleCode();
17:   const text = messages[localeCode] ?? messages["zh-CN"]!;
18:   const [expanded, setExpanded] = useState(true);
19:   const bodyId = useId();
20: 
21:   const headerActions = props.renderSlot ? props.renderSlot("headerActions", null) : null;
22:   const body = props.renderSlot ? props.renderSlot("body", null) : null;
23: 
24:   return (
25:     <section className="quick-help-card" aria-label={text.title}>
26:       <div className="quick-help-card__header">
27:         <button
28:           type="button"
29:           className="quick-help-card__toggle"
30:           aria-expanded={expanded}
31:           aria-controls={bodyId}
32:           onClick={() => setExpanded((value) => !value)}
33:         >
34:           <span className="quick-help-card__title">{text.title}</span>
35:           <span className="quick-help-card__indicator" aria-hidden="true">
36:             {expanded ? "▾" : "▸"}
37:           </span>
38:           <span className="quick-help-card__toggle-label">
39:             {expanded ? text.collapse : text.expand}
40:           </span>
41:         </button>
42:         {headerActions ? (
43:           <div className="quick-help-card__header-actions">{headerActions}</div>
44:         ) : null}
45:       </div>
46:       <div className="quick-help-card__body" id={bodyId} hidden={!expanded}>
47:         {body}
48:       </div>
49:     </section>
50:   );
51: }
